        statistics::Scalar numStuckAtZero;
        statistics::Scalar numStuckAtOne;
        statistics::Scalar numPermanentFaults;

        CHAOSRegStats(statistics::Group *parent);
      };

      std::unique_ptr<CHAOSRegStats> stats;
  };

} // namespace gem5
#endif // __CHAOSReg_HH__

