void
CHAOSPhysReg::readTraceCheck()
{
    // Poll the PhysRegFile's read counter for the traced phys slot.
    // Write a poll line each time so the LAST line holds the final count
    // even if the sim ends via exit syscall (not thread Halted) or aborts
    // mid-run. Python parser takes the last ReadTracePoll line.
    read_count_after_inject = cpu->physRegFile().getReadCountAfter();
    if (write_log) {
        *(log_stream->stream())
            << "ReadTracePoll: cycle " << cpu->curCycle()
            << " PhysReg[" << traced_phys_idx
            << "] read_count=" << read_count_after_inject
            << std::endl;
    }
    // reschedule until the sim stops (exit syscall / abort); the event
    // queue is drained on sim end so this simply stops being called.
    bool any_active = false;
    for (ThreadID tid = 0; tid < cpu->numThreads; ++tid) {
        gem5::ThreadContext *thread_context = cpu->getContext(tid);
        if (thread_context && thread_context->status() != ThreadContext::Halted) {
            any_active = true; break;
        }
    }
    if (any_active) {
        schedule(readTraceEvent, cpu->clockEdge(Cycles(100000)));
    } else {
        // final
        if (write_log) {
            *(log_stream->stream())
