/*
 * SHA-256 for CHAOS fault-injection BM (low-ILP, dependency-chain-heavy,
 * "every bit matters"). Compact reference impl, deterministic input.
 *
 * Build (aarch64 native, static): gcc -static -O2 -o sha256 sha256.c
 * Tune wall-clock by NUM_BLOCKS (each block = one compression call, 64 rounds).
 */
#include <stdio.h>
#include <stdint.h>
#include <string.h>

#define NUM_BLOCKS 12000   /* tune for ~20-40s wall in gem5 O3 */

static const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

#define ROTR(x,n) (((x) >> (n)) | ((x) << (32 - (n))))
#define CH(x,y,z)  (((x) & (y)) ^ (~(x) & (z)))
#define MAJ(x,y,z) (((x) & (y)) ^ ((x) & (z)) ^ ((y) & (z)))
#define BSIG0(x) (ROTR(x,2) ^ ROTR(x,13) ^ ROTR(x,22))
#define BSIG1(x) (ROTR(x,6) ^ ROTR(x,11) ^ ROTR(x,25))
#define SSIG0(x) (ROTR(x,7) ^ ROTR(x,18) ^ ((x) >> 3))
#define SSIG1(x) (ROTR(x,17) ^ ROTR(x,19) ^ ((x) >> 10)))

static void sha256_block(uint32_t *h, const uint8_t *blk) {
    uint32_t w[64];
    for (int i = 0; i < 16; i++) {
        w[i] = ((uint32_t)blk[i*4] << 24) | ((uint32_t)blk[i*4+1] << 16) |
               ((uint32_t)blk[i*4+2] << 8) | (uint32_t)blk[i*4+3];
    }
    for (int i = 16; i < 64; i++) {
        w[i] = SSIG1(w[i-2]) + w[i-7] + SSIG0(w[i-15]) + w[i-16];
    }
    uint32_t a=h[0],b=h[1],c=h[2],d=h[3],e=h[4],f=h[5],g=h[6],hh=h[7];
    for (int i = 0; i < 64; i++) {
        uint32_t t1 = hh + BSIG1(e) + CH(e,f,g) + K[i] + w[i];
        uint32_t t2 = BSIG0(a) + MAJ(a,b,c);
        hh=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    h[0]+=a; h[1]+=b; h[2]+=c; h[3]+=d; h[4]+=e; h[5]+=f; h[6]+=g; h[7]+=hh;
}

int main(void) {
    static uint8_t block[64];
    /* deterministic block content (every byte matters type) */
    uint32_t seed = 0xA5A5A5A5;
    for (int i = 0; i < 64; i++) {
        seed = seed * 1103515245u + 12345u;
        block[i] = (uint8_t)(seed >> 16);
    }
    /* set last 8 bytes as a counter so each block differs */
    uint32_t h[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                     0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    for (int b = 0; b < NUM_BLOCKS; b++) {
        block[56] = (uint8_t)(b >> 24);
        block[57] = (uint8_t)(b >> 16);
        block[58] = (uint8_t)(b >> 8);
        block[59] = (uint8_t)(b);
        block[60] = (uint8_t)(b >> 24);
        block[61] = (uint8_t)(b >> 16);
        block[62] = (uint8_t)(b >> 8);
        block[63] = (uint8_t)(b);
        sha256_block(h, block);
    }
    /* deterministic output: final hash of the running state */
    printf("SHA=%08x%08x%08x%08x%08x%08x%08x%08x\n",
           h[0],h[1],h[2],h[3],h[4],h[5],h[6],h[7]);
    return 0;
}

